export function adicionarPedido(pedidos, pedido) {
  if (!Array.isArray(pedidos)) {
    throw new Error('pedidos precisa ser uma lista');
  }
  pedidos.push(pedido);
  return pedidos;
}

export function buscarPedido(pedidos, id) {
  if (!Array.isArray(pedidos)) {
    throw new Error('pedidos precisa ser uma lista');
  }
  return pedidos.find((pedido) => pedido.id === id);
}

export function totalDoPedido(itens) {
  if (!Array.isArray(itens)) {
    throw new Error('itens precisa ser uma lista');
  }
  return itens.reduce((total, item) => total + item.preco * item.quantidade, 0);
}

