import { totalDoPedido } from './pedidos.mjs';

export function pedidosDoDia(pedidos, dia) {
  if (!Array.isArray(pedidos)) {
    throw new Error('pedidos precisa ser uma lista');
  }
  return pedidos.filter((pedido) => pedido.dia === dia);
}

export function totalDoDia(pedidos, dia) {
  const doDia = pedidosDoDia(pedidos, dia);
  return doDia.reduce((total, pedido) => total + totalDoPedido(pedido.itens), 0);
}

export function todosEntregues(pedidos) {
  if (!Array.isArray(pedidos)) {
    throw new Error('pedidos precisa ser uma lista');
  }
  return pedidos.every((pedido) => pedido.entregue === true);
}

export function produtosMaisVendidos(pedidos) {
  if (!Array.isArray(pedidos)) {
    throw new Error('pedidos precisa ser uma lista');
  }
  const nomes = pedidos.flatMap((pedido) => pedido.itens).map((item) => item.nome);
  const contagem = {};
  for (const nome of nomes) {
    contagem[nome] = (contagem[nome] ?? 0) + 1;
  }
  return Object.entries(contagem)
    .sort((a, b) => b[1] - a[1])
    .map(([nome]) => nome);
}

