import { test } from 'node:test';
import assert from 'node:assert/strict';
import { adicionarPedido, buscarPedido, totalDoPedido } from './lib/pedidos.mjs';
import { pedidosDoDia, totalDoDia, todosEntregues, produtosMaisVendidos } from './lib/relatorio.mjs';

test('adicionarPedido coloca o pedido no fim da lista', () => {
  const pedidos = [];
  adicionarPedido(pedidos, { id: 1, dia: '2026-08-27' });
  adicionarPedido(pedidos, { id: 2, dia: '2026-08-28' });
  assert.equal(pedidos.length, 2);
  assert.equal(pedidos[1].id, 2);
});

test('buscarPedido acha pelo id e devolve undefined quando não existe', () => {
  const pedidos = [{ id: 1, nome: 'Ana' }, { id: 2, nome: 'Beto' }];
  assert.deepEqual(buscarPedido(pedidos, 2), { id: 2, nome: 'Beto' });
  assert.equal(buscarPedido(pedidos, 99), undefined);
});

test('totalDoPedido soma preço vezes quantidade de cada item', () => {
  const itens = [
    { nome: 'X-burguer', preco: 15, quantidade: 1 },
    { nome: 'Refrigerante', preco: 6, quantidade: 2 }
  ];
  assert.equal(totalDoPedido(itens), 27);
  assert.equal(totalDoPedido([]), 0);
});

test('pedidosDoDia filtra os pedidos daquele dia', () => {
  const pedidos = [
    { id: 1, dia: '2026-08-27' },
    { id: 2, dia: '2026-08-28' },
    { id: 3, dia: '2026-08-27' }
  ];
  const doDia = pedidosDoDia(pedidos, '2026-08-27');
  assert.equal(doDia.length, 2);
  assert.equal(doDia[0].id, 1);
});

test('totalDoDia soma os totais dos pedidos do dia (usa totalDoPedido do outro arquivo)', () => {
  const pedidos = [
    { id: 1, dia: '2026-08-27', itens: [
      { nome: 'X-burguer', preco: 15, quantidade: 1 },
      { nome: 'Refrigerante', preco: 6, quantidade: 2 }
    ] },
    { id: 2, dia: '2026-08-27', itens: [{ nome: 'Pizza', preco: 30, quantidade: 1 }] },
    { id: 3, dia: '2026-08-28', itens: [{ nome: 'Pastel', preco: 8, quantidade: 1 }] }
  ];
  assert.equal(totalDoDia(pedidos, '2026-08-27'), 57);
});

test('todosEntregues exige que TODOS estejam entregues', () => {
  assert.equal(todosEntregues([{ entregue: true }, { entregue: true }]), true);
  assert.equal(todosEntregues([{ entregue: true }, { entregue: false }]), false);
  assert.equal(todosEntregues([]), true);
});

test('produtosMaisVendidos lista do mais para o menos vendido', () => {
  const pedidos = [
    { itens: [{ nome: 'X-burguer' }, { nome: 'Refrigerante' }] },
    { itens: [{ nome: 'X-burguer' }] },
    { itens: [{ nome: 'Pastel' }] }
  ];
  assert.deepEqual(produtosMaisVendidos(pedidos), ['X-burguer', 'Refrigerante', 'Pastel']);
});
